const MAX_UINT32 = 2 ** 32 - 1;

/**
 * Reads what the other device sent - null for anything that is not a
 * message of this version. The other device is not trusted: every field is
 * checked, and what reaches the match is on the input grid.
 */
export function parseNetMessage(data: unknown): NetMessage | null {
  const value = typeof data === 'string' ? parseJson(data) : null;
  if (!isObject(value)) {
    return null;
  }
  switch (value['k']) {
    case 'hello': {
      const { v, id, r } = value;
      if (typeof v !== 'string') {
        return null;
      }
      // Whatever else it offers, every device runs the CPU's ruleset.
      const offers: Ruleset[] = Array.isArray(r)
        ? r.filter(isRuleset).filter((ruleset) => ruleset !== 'cpu')
        : [];
      return {
        k: 'hello',
        v,
        id: isPlayerId(id) ? id : null,
        r: ['cpu', ...new Set(offers)],
        f: parseFeatures(value['f']),
      };
    }
    case 'room': {
      const { wish, ready } = value;
      return (wish === null || isMatchLevel(wish)) && typeof ready === 'boolean'
        ? { k: 'room', wish, ready }
        : null;
    }
    case 'setup': {
      const setup = parseSetup(value);
      return setup === null ? null : { k: 'setup', ...setup };
    }
    case 'colors': {
      const colors = validColorPair(value['colors']);
      return colors === null ? null : { k: 'colors', colors };
    }
    case 'start': {
      const setup = parseSetup(value);
      const { seed, n, ruleset } = value;
      return setup === null ||
        !isUpTo(seed, MAX_UINT32) ||
        !isUpTo(n, MAX_UINT32) ||
        !isRuleset(ruleset)
        ? null
        : { k: 'start', n, ...setup, seed, ruleset };
    }
    case 'in': {
      const { t, n } = value;
      const steer = parsePair(value['steer'], 1);
      const drag =
        value['drag'] === null ? null : parsePair(value['drag'], 1e5);
      const boost = value['boost'];
      if (
        !isUpTo(t, MAX_TICK) ||
        !isUpTo(n, MAX_UINT32) ||
        steer === null ||
        (drag === null && value['drag'] !== null) ||
        typeof boost !== 'boolean'
      ) {
        return null;
      }
      return { k: 'in', n, t, steer, drag, boost };
    }
    case 'sum': {
      const { t, h, n } = value;
      return isUpTo(t, MAX_TICK) &&
        isUpTo(h, MAX_UINT32) &&
        isUpTo(n, MAX_UINT32)
        ? { k: 'sum', n, t, h }
        : null;
    }
    case 'bye':
      return { k: 'bye' };
